CREATE DATABASE IF NOT EXISTS ewalel_designed CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE ewalel_designed;
CREATE TABLE IF NOT EXISTS admins (id BIGINT PRIMARY KEY AUTO_INCREMENT,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cottages (id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(160) NOT NULL,location VARCHAR(255) NOT NULL,description TEXT,nightly_rate DECIMAL(12,2) NOT NULL DEFAULT 0,capacity INT NOT NULL DEFAULT 2,photo_url TEXT,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS bookings (id BIGINT PRIMARY KEY AUTO_INCREMENT,cottage_id BIGINT NOT NULL,guest_name VARCHAR(160) NOT NULL,guest_email VARCHAR(190) NOT NULL,guest_phone VARCHAR(40),check_in DATE NOT NULL,check_out DATE NOT NULL,guests INT NOT NULL,total_amount DECIMAL(12,2) NOT NULL,status ENUM('pending','confirmed','cancelled','checked_in','checked_out') NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (cottage_id) REFERENCES cottages(id),INDEX (cottage_id,check_in,check_out));
CREATE TABLE IF NOT EXISTS payments (id BIGINT PRIMARY KEY AUTO_INCREMENT,booking_id BIGINT NOT NULL,method ENUM('mpesa','card','cash') NOT NULL,amount DECIMAL(12,2) NOT NULL,reference VARCHAR(120) UNIQUE,status ENUM('pending','completed','failed','refunded') NOT NULL DEFAULT 'pending',paid_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (booking_id) REFERENCES bookings(id));
CREATE TABLE IF NOT EXISTS maintenance (id BIGINT PRIMARY KEY AUTO_INCREMENT,cottage_id BIGINT NOT NULL,task VARCHAR(255) NOT NULL,scheduled_date DATE NOT NULL,assigned_to VARCHAR(160),estimated_cost DECIMAL(12,2) DEFAULT 0,actual_cost DECIMAL(12,2) NULL,notes TEXT,status ENUM('scheduled','in_progress','completed','cancelled') NOT NULL DEFAULT 'scheduled',completed_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (cottage_id) REFERENCES cottages(id));
